#include <algorithm>
#include <cstdio>
#include <queue>
#define Maxn 5500
#define Maxm 35500
#define INF 1000000000
using namespace std;
struct LinkEdge
{int nxt,t,c,l;}edges[Maxm];
int head[Maxn],edgeCount=1;
void addEdge(int from,int to,int capacity,int cost){
  edges[++edgeCount]=(LinkEdge){head[from],to,capacity,cost};head[from]=edgeCount;
  edges[++edgeCount]=(LinkEdge){head[to],from,0,-cost};head[to]=edgeCount;
}
int S,T,preNode[Maxn],linkPos[Maxn],flowVal[Maxn],dist[Maxn];
bool inQueue[Maxn];
queue<int> q;
int spfa()
{
  for (int i=1;i<=T;i++)
    {dist[i]=INF;flowVal[i]=0;}
  flowVal[S]=INF;dist[S]=0;
  q.push(S);inQueue[S]=true;
  while(!q.empty()){
    int u=q.front();
    inQueue[u]=false;q.pop();
    for (int i=head[u],v;i;i=edges[i].nxt)
      if (edges[i].c&&dist[v=edges[i].t]>dist[u]+edges[i].l){
        dist[v]=dist[u]+edges[i].l;
        flowVal[v]=min(flowVal[u],edges[i].c);
        linkPos[v]=i;preNode[v]=u;
        if (!inQueue[v]){inQueue[v]=true;q.push(v);}
     }
  }return flowVal[T];
}
int n,m,k,C,D,pl[105][105],st[105][105];
struct Data
{int f,t;}s[105];
#define P(x,y) ((x)*n+(y))
int main()
{
  scanf("%d%d%d%d%d",&n,&m,&k,&C,&D);
  S=P(n+k,n)+1;T=S+2;
  addEdge(P(0,1),T,INF,0);
  for (int i=1,p;i<=k;i++){
    scanf("%d",&p);
    addEdge(S,P(0,p),1,0);
  }for (int i=1;i<=m;i++){
    scanf("%d%d",&s[i*2].f,&s[i*2].t);
    s[i*2-1]=(Data){s[i*2].t,s[i*2].f};
  }m*=2;
  for (int t=1;t<=n+k;t++){
    for (int i=1;i<=n;i++)
      addEdge(P(t-1,i),P(t,i),INF,0);
    for (int i=1;i<=m;i++){
      addEdge(P(t-1,s[i].f),P(t,s[i].t),1,D);
      pl[t][i]=tl;st[t][i]=1;
    }addEdge(P(t,1),T,INF,t*C);
  }
  int totalFlow=0,totalCost=0;
  while(int flow_now=spfa()){
    int u=T;
    while(u!=S){
      int last=preNode[u];
      edges[linkPos[u]].c-=flow_now;
      edges[linkPos[u]^1].c+=flow_now;
      u=last;
    }
    totalCost+=dist[T]*flow_now;
    for (int t=1;t<=n+n;t++)
      for (int i=1;i<=m;i++)
        if (edges[pl[t][i]].c){
          st[t][i]++;
          addEdge(P(t-1,s[i].f),P(t,s[i].t),1,D*(st[t][i]*2-1));
          pl[t][i]=tl;
        }
  }printf("%d\n",totalCost);
  return 0;
}
